import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, TypeformWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      brevoApiKey: 'test-api-key',
      defaultListId: 123,
      fetch
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as TypeformWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.contactId).toBe(12345)
    expect(result.email).toBe('laura@example.com')
    expect(result.listIds).toEqual([123])
  })
})

describe('handle', () => {
  let calls: RecordedCall[]
  let fetch: typeof fetch
  let baseConfig: ConnectorConfig

  beforeEach(() => {
    const fake = fakeFetch((req) => {
      if (req.url === 'https://api.brevo.com/v3/contacts' && req.method === 'POST') {
        return jsonResponse({ id: 999 }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })
    fetch = fake.fetch
    calls = fake.calls
    baseConfig = {
      brevoApiKey: 'test-key-123',
      defaultListId: 42,
      fetch
    }
  })

  it('happy path: creates contact with email, name, and default list', async () => {
    const payload: TypeformWebhookPayload = {
      event_id: 'evt-1',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-1',
        token: 'tok-1',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'john@example.com', field: { id: 'f1', type: 'email' } },
          { type: 'text', text: 'John Doe', field: { id: 'f2', type: 'short_text' } }
        ]
      }
    }

    const result = await handle(payload, baseConfig)

    expect(result).toEqual({
      contactId: 999,
      email: 'john@example.com',
      listIds: [42]
    })

    expect(calls).toHaveLength(1)
    const call = calls[0]
    expect(call.method).toBe('POST')
    expect(call.url).toBe('https://api.brevo.com/v3/contacts')
    expect(call.headers.get('api-key')).toBe('test-key-123')
    expect(call.json).toEqual({
      email: 'john@example.com',
      attributes: { FNAME: 'John', LNAME: 'Doe' },
      listIds: [42]
    })
  })

  it('uses fieldIdToListId mapping to add additional list IDs', async () => {
    const payload: TypeformWebhookPayload = {
      event_id: 'evt-2',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-1',
        token: 'tok-2',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'jane@example.com', field: { id: 'f1', type: 'email' } },
          { type: 'text', text: 'Jane Smith', field: { id: 'f2', type: 'short_text' } },
          { type: 'multiple_choice', text: 'Option A', field: { id: 'list-field-1', type: 'multiple_choice' } }
        ]
      }
    }

    const config: ConnectorConfig = {
      ...baseConfig,
      fieldIdToListId: { 'list-field-1': 99 }
    }

    const result = await handle(payload, config)

    expect(result.listIds).toEqual([42, 99])
    expect(calls[0].json).toEqual({
      email: 'jane@example.com',
      attributes: { FNAME: 'Jane', LNAME: 'Smith' },
      listIds: [42, 99]
    })
  })

  it('handles missing last name (single word name)', async () => {
    const payload: TypeformWebhookPayload = {
      event_id: 'evt-3',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-1',
        token: 'tok-3',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'cher@example.com', field: { id: 'f1', type: 'email' } },
          { type: 'text', text: 'Cher', field: { id: 'f2', type: 'short_text' } }
        ]
      }
    }

    const result = await handle(payload, baseConfig)

    expect(result.email).toBe('cher@example.com')
    expect(calls[0].json).toEqual({
      email: 'cher@example.com',
      attributes: { FNAME: 'Cher', LNAME: '' },
      listIds: [42]
    })
  })

  it('throws when email is missing from answers', async () => {
    const payload: TypeformWebhookPayload = {
      event_id: 'evt-4',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-1',
        token: 'tok-4',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'text', text: 'No Email', field: { id: 'f2', type: 'short_text' } }
        ]
      }
    }

    await expect(handle(payload, baseConfig)).rejects.toThrow('Required field missing: email not found in form answers')
  })

  it('throws when form_response.answers is missing', async () => {
    const payload = {
      event_id: 'evt-5',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-1',
        token: 'tok-5',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: []
      }
    } as unknown as TypeformWebhookPayload

    await expect(handle(payload, baseConfig)).rejects.toThrow('Invalid payload: missing form_response.answers')
  })

  it('throws when brevoApiKey is missing from config', async () => {
    const payload: TypeformWebhookPayload = {
      event_id: 'evt-6',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-1',
        token: 'tok-6',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'test@example.com', field: { id: 'f1', type: 'email' } }
        ]
      }
    }

    const config: ConnectorConfig = { ...baseConfig, brevoApiKey: '' }

    await expect(handle(payload, config)).rejects.toThrow('Missing required config: brevoApiKey')
  })

  it('throws when defaultListId is missing from config', async () => {
    const payload: TypeformWebhookPayload = {
      event_id: 'evt-7',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-1',
        token: 'tok-7',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'test@example.com', field: { id: 'f1', type: 'email' } }
        ]
      }
    }

    const config: ConnectorConfig = { ...baseConfig, defaultListId: 0 as unknown as number }

    await expect(handle(payload, config)).rejects.toThrow('Missing required config: defaultListId')
  })

  it('throws on non-2xx response from Brevo API', async () => {
    const errorFetch = fakeFetch(() => jsonResponse({ error: 'contact exists' }, 400))

    const payload: TypeformWebhookPayload = {
      event_id: 'evt-8',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-1',
        token: 'tok-8',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'exists@example.com', field: { id: 'f1', type: 'email' } }
        ]
      }
    }

    await expect(handle(payload, { ...baseConfig, fetch: errorFetch.fetch })).rejects.toThrow(
      'Brevo API error: 400 Bad Request at POST https://api.brevo.com/v3/contacts'
    )
  })

  it('includes response body in error message on failure', async () => {
    const errorFetch = fakeFetch(() => jsonResponse({ code: 'DUPLICATE', message: 'Contact already exists' }, 400))

    const payload: TypeformWebhookPayload = {
      event_id: 'evt-9',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-1',
        token: 'tok-9',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'dup@example.com', field: { id: 'f1', type: 'email' } }
        ]
      }
    }

    try {
      await handle(payload, { ...baseConfig, fetch: errorFetch.fetch })
    } catch (e) {
      expect(String(e)).toContain('Contact already exists')
    }
  })

  it('deduplicates listIds when mapping produces duplicates', async () => {
    const payload: TypeformWebhookPayload = {
      event_id: 'evt-10',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-1',
        token: 'tok-10',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'dedupe@example.com', field: { id: 'f1', type: 'email' } },
          { type: 'text', text: 'Test User', field: { id: 'f2', type: 'short_text' } },
          { type: 'multiple_choice', text: 'Option', field: { id: 'same-list', type: 'multiple_choice' } },
          { type: 'multiple_choice', text: 'Option', field: { id: 'same-list', type: 'multiple_choice' } }
        ]
      }
    }

    const config: ConnectorConfig = {
      ...baseConfig,
      fieldIdToListId: { 'same-list': 42 } // Same as defaultListId
    }

    const result = await handle(payload, config)
    expect(result.listIds).toEqual([42])
  })
})

