  trelloApiKey: string;
  trelloApiToken: string;
  trelloListId: string;
  cardName: string;
  calWebhookSecret?: string;
  fetch?: typeof fetch;
}

export interface CalWebhookPayload {
  triggerEvent: string;
  payload: {
    attendees: Array<{
      email: string;
      name: string;
    }>;
  };
