import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, HubSpotDealWebhookPayload } from './connector';
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      instanceUrl: 'https://test.my.salesforce.com',
      accessToken: 'test-access-token',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as HubSpotDealWebhookPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.upsert.id).toBe('001xx000003DGHAAO');
    expect(result.upsert.created).toBe(false);
  });
});

describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    instanceUrl: 'https://test.my.salesforce.com',
    accessToken: 'test-access-token',
  };

  const basePayload = SOURCE_EXAMPLE as unknown as HubSpotDealWebhookPayload;

  it('happy path: upsert succeeds with created=false', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'PATCH' && req.url.includes('/Domain__c/')) {
        return jsonResponse({ id: '001xx000003DGHAAO', success: true, errors: [], created: false }, 200);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const config = { ...baseConfig, fetch };
    const result = await handle(basePayload, config);
    expect(calls.length).toBe(1);
    expect(calls[0].method).toBe('PATCH');
    expect(calls[0].url).toBe('https://test.my.salesforce.com/services/data/v68.0/sobjects/Account/Domain__c/acme.com');
    expect(calls[0].headers.get('authorization')).toBe('Bearer test-access-token');
    expect(calls[0].json).toEqual({
      Name: 'Acme Corp',
      Website: 'acme.com',
      Domain__c: 'acme.com',
      Account_Name__c: 'Acme Corp Deal',
      Annual_Revenue: 50000,
      StageName: 'qualifiedtobuy',
    });
    expect(result.upsert.id).toBe('001xx000003DGHAAO');
    expect(result.upsert.created).toBe(false);
    expect(result.create).toBeUndefined();
  });

  it('auth mechanism: sends Bearer token in Authorization header', async () => {
    const { fetch, calls } = fakeFetch((req) => jsonResponse({ id: '123', success: true, errors: [], created: true }, 201));
    const config = { ...baseConfig, fetch };
    await handle(basePayload, config);
    expect(calls[0].headers.get('authorization')).toBe('Bearer test-access-token');
  });

  it('field mapping: maps deal properties to Salesforce fields correctly', async () => {
    const { fetch, calls } = fakeFetch((req) => jsonResponse({ id: '123', success: true, errors: [], created: true }, 201));
    const config = { ...baseConfig, fetch };
    const payload = {
      ...SOURCE_EXAMPLE,
      properties: {
        ...SOURCE_EXAMPLE.properties,
        company_name: 'Test Corp',
        domain: 'test.com',
        dealname: 'Test Deal',
        amount: '100000',
        dealstage: 'proposal',
      },
    } as unknown as HubSpotDealWebhookPayload;
    await handle(payload, config);
    expect(calls[0].json).toEqual({
      Name: 'Test Corp',
      Website: 'test.com',
      Domain__c: 'test.com',
      Account_Name__c: 'Test Deal',
      Annual_Revenue: 100000,
      StageName: 'proposal',
    });
  });

  it('throws on missing required field: properties.company_name', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config = { ...baseConfig, fetch };
    const payload = {
      ...SOURCE_EXAMPLE,
      properties: { ...SOURCE_EXAMPLE.properties, company_name: undefined },
    } as unknown as HubSpotDealWebhookPayload;
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: properties.company_name');
  });

  it('throws on missing required field: properties.domain', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config = { ...baseConfig, fetch };
    const payload = {
      ...SOURCE_EXAMPLE,
      properties: { ...SOURCE_EXAMPLE.properties, domain: undefined },
    } as unknown as HubSpotDealWebhookPayload;
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: properties.domain');
  });

  it('throws on missing required field: properties.dealname', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config = { ...baseConfig, fetch };
    const payload = {
      ...SOURCE_EXAMPLE,
      properties: { ...SOURCE_EXAMPLE.properties, dealname: undefined },
    } as unknown as HubSpotDealWebhookPayload;
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: properties.dealname');
  });

  it('throws on missing required field: properties.amount', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config = { ...baseConfig, fetch };
    const payload = {
      ...SOURCE_EXAMPLE,
      properties: { ...SOURCE_EXAMPLE.properties, amount: undefined },
    } as unknown as HubSpotDealWebhookPayload;
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: properties.amount');
  });

  it('throws on missing required field: properties.dealstage', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config = { ...baseConfig, fetch };
    const payload = {
      ...SOURCE_EXAMPLE,
      properties: { ...SOURCE_EXAMPLE.properties, dealstage: undefined },
    } as unknown as HubSpotDealWebhookPayload;
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: properties.dealstage');
  });

  it('throws on non-2xx response from upsert (e.g., 401)', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401));
    const config = { ...baseConfig, fetch };
    await expect(handle(basePayload, config)).rejects.toThrow('Salesforce upsert failed: 401 Unauthorized for PATCH');
    expect(calls[0].method).toBe('PATCH');
  });

  it('falls back to create when upsert returns 300 (multiple matches)', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'PATCH' && req.url.includes('/Domain__c/')) {
        return jsonResponse({ errorCode: 'MULTIPLE_MATCHES', message: 'Multiple matches found' }, 300);
      }
      if (req.method === 'POST' && req.url.endsWith('/sobjects/Account/')) {
        return jsonResponse({ id: '001xx000003DGHAAO', success: true, errors: [] }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const config = { ...baseConfig, fetch };
    const result = await handle(basePayload, config);
    expect(calls.length).toBe(2);
    expect(calls[0].method).toBe('PATCH');
    expect(calls[1].method).toBe('POST');
    expect(calls[1].url).toBe('https://test.my.salesforce.com/services/data/v68.0/sobjects/Account/');
    expect(result.upsert.id).toBe('');
    expect(result.upsert.created).toBe(false);
    expect(result.create?.id).toBe('001xx000003DGHAAO');
  });

  it('throws if create also fails after 300', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'PATCH') return jsonResponse({ error: 'Multiple matches' }, 300);
      if (req.method === 'POST') return jsonResponse({ error: 'Server error' }, 500);
      return jsonResponse({}, 404);
    });
    const config = { ...baseConfig, fetch };
    await expect(handle(basePayload, config)).rejects.toThrow('Salesforce create failed: 500 Internal Server Error for POST');
    expect(calls.length).toBe(2);
  });
});

