export interface ZendeskTicketPayload {
  ticket: {
    id: number
    subject: string
    description: string
    status: string
    priority: string
    requester_id: number
    submitter_id: number
    assignee_id: number | null
    group_id: number | null
    organization_id: number | null
    tags: string[]
    created_at: string
    updated_at: string
  }
